import React from "react";
import {
  FaCode,
  FaAward,
  FaLaptopCode,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaExternalLinkAlt
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      <div className="glow"></div>

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Expertise</h1>
        <p>
          An overview of my technical skills, tools, and practical experience.
        </p>
      </div>

      {/* TOP CARDS */}
      <div className="bento">

        {/* TECH */}
        <div className="card">
          <h2><FaCode /> Tech Stack</h2>
          <div className="tags">
            <span>Java</span>
            <span>React.js</span>
            <span>Spring Boot</span>
            <span>MySQL</span>
            <span>HTML</span>
            <span>CSS</span>
            <span>JavaScript</span>
            <span>Power BI</span>
          </div>
        </div>

        {/* CODING */}
        <div className="card highlight">
          <h2><FaLaptopCode /> Coding Profiles</h2>

          <div className="profiles">
            <a href="https://leetcode.com/" target="_blank" rel="noreferrer">
              <div>
                <span>LeetCode</span>
                <p>50+ Problems Solved</p>
              </div>
              <FaExternalLinkAlt />
            </a>

            <a href="https://www.hackerrank.com" target="_blank" rel="noreferrer">
              <div>
                <span>HackerRank</span>
                <p>5★ Problem Solving</p>
              </div>
              <FaExternalLinkAlt />
            </a>
          </div>
        </div>

        {/* CERTIFICATIONS */}
        <div className="card">
          <h2><FaAward /> Certifications</h2>
          <div className="list">
            <p>✔ Java Programming – NPTEL</p>
            <p>✔ Data Science – NPTEL</p>
            <p>✔ SQL – HackerRank</p>
            <p>✔ Python – SoloLearn</p>
          </div>
        </div>

      </div>

      {/* INTERNSHIP */}
      <div className="timeline-section">
        <h2>Internship Experience</h2>

        <div className="timeline">

          <div className="item">
            <div className="content">
              <div className="title-row">
                <span className="dot"></span>
                <h3>Full Stack Java Intern</h3>
              </div>

              <h4>Retech Solutions</h4>

              <ul>
                <li>Developed a Student Portal using Spring Boot, REST APIs, and MySQL</li>
                <li>Implemented secure authentication and user management features</li>
